<?php
declare(strict_types=1);
const SV3_CONTRACT='2026-10-08-safety-vote-phase3-r1';
const SV3_TYPES=['single_choice','multiple_choice','yes_no_abstain','rating','likert','ranking','matrix','allocation','token','short_text','long_text','date_time','employee_picker','organization_picker','file_upload'];
const SV3_OPTION_TYPES=['single_choice','multiple_choice','yes_no_abstain','likert','ranking','matrix','allocation','token'];
const SV3_TEXT_TYPES=['short_text','long_text','employee_picker','organization_picker'];
const SV3_SECRET_BLOCKED=['short_text','long_text','employee_picker','organization_picker','file_upload','matrix'];
function sv3_text($v,int$n=300):string{return mb_substr(trim(preg_replace('/\s+/u',' ',preg_replace('/[\x00-\x1F\x7F]/u',' ',(string)($v??'')))),0,$n);}
function sv3_long($v,int$n=10000):string{return mb_substr(trim(str_replace("\0",'',(string)($v??''))),0,$n);}
function sv3_int($v):?int{$n=filter_var($v,FILTER_VALIDATE_INT);return$n!==false&&$n>0?(int)$n:null;}
function sv3_num($v):?float{return is_numeric($v)?(float)$v:null;}
function sv3_obj($v):array{if(is_string($v))$v=json_decode($v,true);return is_array($v)?$v:[];}
function sv3_condition($v):?array{$x=sv3_obj($v);$code=strtoupper(sv3_text($x['questionCode']??'',50));$op=strtolower(sv3_text($x['operator']??'',20));if(!$code&&!$op)return null;if(!$code||!in_array($op,['equals','not_equals','includes','not_includes','answered','not_answered'],true))return['invalid'=>true];$value=$x['value']??'';if(is_array($value))$value=array_slice(array_map(fn($y)=>sv3_text($y,100),$value),0,100);else$value=sv3_text($value,100);return['questionCode'=>$code,'operator'=>$op,'value'=>$value];}
function sv3_validation($v):array{$x=sv3_obj($v);$out=[];foreach(['minNumber','maxNumber','minLength','maxLength','totalMax']as$k)if(isset($x[$k])&&$x[$k]!==''&&is_numeric($x[$k]))$out[$k]=(float)$x[$k];if(isset($x['allowedValues'])&&is_array($x['allowedValues']))$out['allowedValues']=array_slice(array_values(array_filter(array_map(fn($y)=>sv3_text($y,100),$x['allowedValues']))),0,500);return$out;}
function sv3_question(array$in,int$i=0):array{$type=strtolower(sv3_text($in['questionType']??$in['QuestionType']??'',32));$title=sv3_text($in['title']??$in['Title']??'',300);$required=(bool)($in['isRequired']??$in['IsRequired']??true);$min=(int)($in['minSelections']??$in['MinSelections']??($required?1:0));$max=(int)($in['maxSelections']??$in['MaxSelections']??1);$condition=sv3_condition($in['displayCondition']??$in['DisplayConditionJson']??null);$validation=sv3_validation($in['validation']??$in['ValidationJson']??null);$errors=[];if(!in_array($type,SV3_TYPES,true))$errors[]='INVALID_TYPE';if(!$title)$errors[]='TITLE_REQUIRED';if($min<0||$max<1||$min>$max)$errors[]='INVALID_SELECTION_LIMIT';if(in_array($type,['single_choice','yes_no_abstain'],true)&&($min>1||$max!==1))$errors[]='INVALID_SELECTION_LIMIT';if(isset($condition['invalid']))$errors[]='INVALID_DISPLAY_CONDITION';if(isset($validation['minNumber'],$validation['maxNumber'])&&$validation['minNumber']>$validation['maxNumber'])$errors[]='INVALID_NUMERIC_RANGE';if(isset($validation['minLength'],$validation['maxLength'])&&$validation['minLength']>$validation['maxLength'])$errors[]='INVALID_TEXT_RANGE';return['ok'=>!$errors,'errors'=>$errors,'value'=>['id'=>sv3_int($in['id']??null),'questionCode'=>strtoupper(sv3_text($in['questionCode']??$in['QuestionCode']??('Q'.($i+1)),50)),'questionType'=>$type,'title'=>$title,'helpText'=>sv3_text($in['helpText']??$in['HelpText']??'',1000)?:null,'isRequired'=>$required,'minSelections'=>$min,'maxSelections'=>$max,'randomizeOptions'=>(bool)($in['randomizeOptions']??$in['RandomizeOptions']??false),'allowComment'=>(bool)($in['allowComment']??$in['AllowComment']??false),'validation'=>$validation,'displayCondition'=>$condition,'resultVisibility'=>strtolower(sv3_text($in['resultVisibility']??$in['ResultVisibility']??'aggregate',30)),'sortOrder'=>sv3_int($in['sortOrder']??$in['SortOrder']??null)??$i+1,'options'=>is_array($in['options']??null)?$in['options']:[]]];}
function sv3_builder($input,string$privacy='identified'):array{if(!is_array($input)||!$input||count($input)>50)return['ok'=>false,'errors'=>[['index'=>-1,'codes'=>['QUESTION_ARRAY_REQUIRED']]],'questions'=>[]];$parsed=[];$errors=[];$codes=[];foreach(array_values($input)as$i=>$raw){$q=sv3_question((array)$raw,$i);if(!$q['ok'])$errors[]=['index'=>$i,'codes'=>$q['errors']];$code=$q['value']['questionCode'];if(!$code||isset($codes[$code]))$errors[]=['index'=>$i,'codes'=>['QUESTION_CODE_DUPLICATE']];$known=$codes;$codes[$code]=true;if($q['value']['displayCondition']&&!isset($q['value']['displayCondition']['invalid'])&&!isset($known[$q['value']['displayCondition']['questionCode']]))$errors[]=['index'=>$i,'codes'=>['CONDITION_MUST_REFERENCE_EARLIER_QUESTION']];$opts=[];foreach(array_values($q['value']['options'])as$j=>$o)$opts[]=['id'=>sv3_int($o['id']??null),'optionCode'=>strtoupper(sv3_text($o['optionCode']??$o['OptionCode']??('O'.($j+1)),50)),'label'=>sv3_text($o['label']??$o['Label']??'',300),'description'=>sv3_text($o['description']??$o['Description']??'',2000)?:null,'scoreValue'=>sv3_num($o['scoreValue']??$o['ScoreValue']??null),'isAbstain'=>(bool)($o['isAbstain']??$o['IsAbstain']??false),'fileId'=>sv3_int($o['fileId']??$o['FileID']??null),'sortOrder'=>sv3_int($o['sortOrder']??$o['SortOrder']??null)??$j+1];if(in_array($q['value']['questionType'],SV3_OPTION_TYPES,true)&&(count($opts)<2||count($opts)>100||array_filter($opts,fn($o)=>!$o['label'])))$errors[]=['index'=>$i,'codes'=>['OPTIONS_INVALID']];if(!in_array($q['value']['questionType'],SV3_OPTION_TYPES,true)&&$opts)$errors[]=['index'=>$i,'codes'=>['OPTIONS_NOT_ALLOWED']];if(($privacy==='secret_ballot'||($privacy==='anonymous'&&$q['value']['questionType']==='file_upload'))&&in_array($q['value']['questionType'],SV3_SECRET_BLOCKED,true))$errors[]=['index'=>$i,'codes'=>['PRIVACY_QUESTION_TYPE_FORBIDDEN']];$q['value']['options']=$opts;$parsed[]=$q['value'];}return['ok'=>!$errors,'errors'=>$errors,'questions'=>$parsed];}
function sv3_signal(?array$q,?array$a){if(!$a)return null;$options=$q['options']??[];$code=function($id)use($options){foreach($options as$o)if((int)$o['id']===(int)$id)return$o['optionCode'];return null;};if(isset($a['optionIds'])&&is_array($a['optionIds']))return array_values(array_filter(array_map($code,$a['optionIds'])));if(isset($a['rankedOptionIds'])&&is_array($a['rankedOptionIds']))return array_values(array_filter(array_map($code,$a['rankedOptionIds'])));if(isset($a['allocations'])&&is_array($a['allocations']))return array_values(array_filter(array_map(fn($x)=>(float)($x['value']??0)>0?$code($x['optionId']??0):null,$a['allocations'])));if(isset($a['matrixValues'])&&is_array($a['matrixValues']))return array_keys($a['matrixValues']);foreach(['numericValue','textValue','dateTimeValue','fileId']as$k)if(isset($a[$k])&&$a[$k]!=='')return$a[$k];return null;}
function sv3_visible(array$q,array$questions,array$map):bool{$c=$q['displayCondition']??null;if(!$c)return true;$parent=null;foreach($questions as$x)if($x['questionCode']===$c['questionCode']){$parent=$x;break;}$value=sv3_signal($parent,$map[(int)($parent['id']??0)]??null);$answered=is_array($value)?count($value)>0:!($value===null||$value==='');if($c['operator']==='answered')return$answered;if($c['operator']==='not_answered')return!$answered;$expected=is_array($c['value'])?array_map('strval',$c['value']):[(string)$c['value']];$actual=is_array($value)?array_map('strval',$value):[(string)($value??'')];if($c['operator']==='equals')return count($actual)===1&&in_array($actual[0],$expected,true);if($c['operator']==='not_equals')return!(count($actual)===1&&in_array($actual[0],$expected,true));if($c['operator']==='includes')return(bool)array_intersect($expected,$actual);if($c['operator']==='not_includes')return!array_intersect($expected,$actual);return false;}
function sv3_answers(array$questions,$raw,string$privacy='identified'):array{if(!is_array($raw))return['ok'=>false,'errors'=>['ANSWERS_REQUIRED'],'answers'=>[]];$by=[];foreach($questions as$q)$by[(int)$q['id']]=$q;$map=[];$errors=[];foreach($raw as$a){$id=sv3_int($a['questionId']??null);if(!$id||!isset($by[$id])||isset($map[$id])){$errors[]='QUESTION_INVALID';continue;}$map[$id]=$a;}$out=[];foreach($questions as$q){$qid=(int)$q['id'];$a=$map[$qid]??null;$visible=sv3_visible($q,$questions,$map);if(!$visible){if($a)$errors[]='HIDDEN_QUESTION_ANSWERED';continue;}if(!$a){if($q['isRequired'])$errors[]='REQUIRED_ANSWER_MISSING';continue;}$allowed=[];foreach($q['options']as$o)$allowed[(int)$o['id']]=true;$x=['questionId'=>$qid,'questionType'=>$q['questionType'],'rows'=>[]];$type=$q['questionType'];if(in_array($type,['single_choice','multiple_choice','yes_no_abstain','likert'],true)){$ids=array_values(array_unique(array_filter(array_map('sv3_int',is_array($a['optionIds']??null)?$a['optionIds']:[]))));if(array_filter($ids,fn($id)=>!isset($allowed[$id]))||count($ids)<(int)$q['minSelections']||count($ids)>(int)$q['maxSelections'])$errors[]='SELECTION_INVALID';else{$x['optionIds']=$ids;foreach($ids as$i=>$id)$x['rows'][]=['optionId'=>$id,'answerOrder'=>$i+1];}}elseif($type==='ranking'){$ids=array_values(array_filter(array_map('sv3_int',is_array($a['rankedOptionIds']??null)?$a['rankedOptionIds']:[])));if(count(array_unique($ids))!==count($ids)||array_filter($ids,fn($id)=>!isset($allowed[$id]))||count($ids)<(int)$q['minSelections']||count($ids)>(int)$q['maxSelections'])$errors[]='RANKING_INVALID';else{$x['rankedOptionIds']=$ids;foreach($ids as$i=>$id)$x['rows'][]=['optionId'=>$id,'rankValue'=>$i+1,'answerOrder'=>$i+1];}}elseif(in_array($type,['allocation','token'],true)){$xs=[];$total=0;foreach(is_array($a['allocations']??null)?$a['allocations']:[]as$v){$id=sv3_int($v['optionId']??null);$num=sv3_num($v['value']??null);$xs[]=['optionId'=>$id,'value'=>$num];$total+=$num??0;}if(!$xs||count(array_unique(array_column($xs,'optionId')))!==count($xs)||array_filter($xs,fn($v)=>!isset($allowed[$v['optionId']])||$v['value']===null||$v['value']<0)||(isset($q['validation']['totalMax'])&&$total>$q['validation']['totalMax']))$errors[]='ALLOCATION_INVALID';else{$x['allocations']=$xs;foreach($xs as$i=>$v)$x['rows'][]=['optionId'=>$v['optionId'],'numericValue'=>$v['value'],'answerOrder'=>$i+1];}}elseif($type==='matrix'){$vals=is_array($a['matrixValues']??null)?$a['matrixValues']:[];if(!$vals||array_filter($vals,fn($v,$k)=>!isset($allowed[(int)$k])||!sv3_text($v,200),ARRAY_FILTER_USE_BOTH))$errors[]='MATRIX_INVALID';else{$x['matrixValues']=$vals;$i=0;foreach($vals as$k=>$v)$x['rows'][]=['optionId'=>(int)$k,'textValue'=>sv3_text($v,200),'answerOrder'=>++$i];}}elseif($type==='rating'){$n=sv3_num($a['numericValue']??null);$v=$q['validation'];if($n===null||(isset($v['minNumber'])&&$n<$v['minNumber'])||(isset($v['maxNumber'])&&$n>$v['maxNumber']))$errors[]='NUMBER_INVALID';else{$x['numericValue']=$n;$x['rows'][]=['numericValue'=>$n,'answerOrder'=>1];}}elseif(in_array($type,SV3_TEXT_TYPES,true)){$v=sv3_long($a['textValue']??'',$type==='short_text'?1000:10000);$rule=$q['validation'];if(!$v||(isset($rule['minLength'])&&mb_strlen($v)<$rule['minLength'])||(isset($rule['maxLength'])&&mb_strlen($v)>$rule['maxLength'])||(isset($rule['allowedValues'])&&!in_array($v,$rule['allowedValues'],true)))$errors[]='TEXT_INVALID';else{$x['textValue']=$v;$x['rows'][]=['textValue'=>$v,'answerOrder'=>1];}}elseif($type==='date_time'){$ts=strtotime((string)($a['dateTimeValue']??''));if(!$ts)$errors[]='DATE_TIME_INVALID';else{$v=gmdate('Y-m-d\\TH:i:s.000\\Z',$ts);$x['dateTimeValue']=$v;$x['rows'][]=['dateTimeValue'=>$v,'answerOrder'=>1];}}elseif($type==='file_upload'){$fid=sv3_int($a['fileId']??null);if(!$fid||in_array($privacy,['anonymous','secret_ballot'],true))$errors[]='FILE_INVALID';else{$x['fileId']=$fid;$x['rows'][]=['fileId'=>$fid,'answerOrder'=>1];}}else$errors[]='QUESTION_TYPE_INVALID';$out[]=$x;}return['ok'=>!$errors,'errors'=>array_values(array_unique($errors)),'answers'=>$out];}
function sv3_key(string$secret):string{return hash('sha256',$secret,true);}
function sv3_encrypt(string$value,string$secret):string{$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($value,'aes-256-gcm',sv3_key($secret),OPENSSL_RAW_DATA,$iv,$tag);return base64_encode($iv).'.'.base64_encode($tag).'.'.base64_encode($cipher);}
function sv3_decrypt(string$value,string$secret):?string{$p=explode('.',$value);if(count($p)!==3)return null;$out=openssl_decrypt(base64_decode($p[2],true),'aes-256-gcm',sv3_key($secret),OPENSSL_RAW_DATA,base64_decode($p[0],true),base64_decode($p[1],true));return$out===false?null:$out;}
